create or replace TABLE IDQ_PRODUCTION.IDQ_RESULTS.IDQ_ADDINFO_GF_STORE_1 (
	ID NUMBER(38,0) NOT NULL autoincrement start 1 increment 1 order,
	TEST_OBJECT_ID NUMBER(38,0),
	BRANCH_ID NUMBER(38,0),
	SOURCE_SYSTEM_PRIMARY_KEY VARCHAR(100),
	SOURCE_SYSTEM_ID NUMBER(38,0),
	COUNTRY_ID NUMBER(38,0),
	IS_RELEVANT NUMBER(38,0),
	STORE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for a store.',
	DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
	DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
	DWH_VALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing the current record, i.e. where the current date is between dwh_valid_from and dwh_valid_to.',
	CURR_STORE_NR VARCHAR(20) NOT NULL COMMENT 'The number by which the store is currently known to business. The store number is identical to the real estate number of the object which currently houses the store. In case the building changes, the store_sid remains unchanged, but the store number gets updated.',
	INIT_STORE_NR VARCHAR(20) NOT NULL COMMENT 'The initial store number, i.e. the number which was assigned to the store before the first relocation or demolition. This number does not change, in case the building changes.',
	STORE_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the store.',
	INT_ORG_STATUS_CD VARCHAR(20) NOT NULL COMMENT 'The code for the retail status_1 of a store. The status_1 codes for <open> and <closed> are strictly connected with the store open date and the store close date, as they are derived from these attributes.',
	INT_ORG_STATUS_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the retail status_1 (open / closed) of a store in group language, i.e. in German.',
	REAL_ESTATE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the real estate object.',
	OPEN_DT DATE COMMENT 'The date when the store has started its regular operation. (This date may be different from the planned opening date.)',
	PLANNED_OPEN_DT DATE COMMENT 'The expected opening date of the store.',
	CLOSE_DT DATE COMMENT 'The closing date of the store as set by WAWI. (NULL if the store is open.)',
	ISO_COUNTRY_CD VARCHAR(2) NOT NULL COMMENT 'The code according to ISO 3166 identifying the country_1, in which the store is located,',
	COUNTRY_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the country_1, in which the store is located,',
	CITY_NAME VARCHAR(100) COMMENT 'The name of the city where the store is located.',
	DISTRICT_NAME VARCHAR(100) COMMENT 'The name of the district, in which the store is located,',
	ZIP VARCHAR(15) COMMENT 'The postal code of the store address.',
	STREET_NAME VARCHAR(100) COMMENT 'The name of the street where the store is located.',
	HOUSE_NR VARCHAR(100) COMMENT 'The number of the building within the street where the store is located.',
	LON NUMBER(9,6) COMMENT 'The geographical longitude of the store address.',
	LAT NUMBER(9,6) COMMENT 'The geographical latitude of the store address.',
	PO_BOX_NR VARCHAR(20) COMMENT 'The post box number of the store. (NULL if the store does not have post box.)',
	PHONE_NR VARCHAR(100) COMMENT 'The telephone number of the store.',
	FAX_NR VARCHAR(100) COMMENT 'The telefax number of the store.',
	EMAIL_ADDR_TXT VARCHAR(1000) COMMENT 'An email address_1 for that store.',
	SALES_MGR_DISTRICT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the organizational unit_1 for which the related sales_1 manager is responsible.',
	SALES_MGR_DISTRICT_NR VARCHAR(20) COMMENT 'The number which identifies the organizational unit_1 for which the related sales_1 manager is responsible.',
	SALES_MGR_DISTRICT_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related sales_1 manager district.',
	SALES_MGR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1, who is currently filling the position of the related sales_1 manager.',
	SALES_MGR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the person who is currently filling the position of the related sales_1 manager.',
	SALES_MGR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the person who is currently filling the position of the related sales_1 manager.',
	ACCT_MGR_DISTRICT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the organizational unit_1 for which the related account_1 manager is responsible.',
	ACCT_MGR_DISTRICT_NR VARCHAR(20) COMMENT 'The number which identifies the organizational unit_1 for which the related account_1 manager is responsible.',
	ACCT_MGR_DISTRICT_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related account_1 manager district.',
	ACCT_MGR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1, who is currently filling the positon of the related account_1 manager.',
	ACCT_MGR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the person who is currently filling the position of the related account_1 manager.',
	ACCT_MGR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the person who is currently filling the position of the related account_1 manager.',
	SALES_COMPANY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the sales_1 company (VGES) to which this store is related.',
	SALES_COMPANY_NR VARCHAR(20) COMMENT 'The number which identifies the sales_1 company (VGES) to which this store is related.',
	SALES_COMPANY_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the sales_1 company to which this store is related..',
	SALES_COMPANY_DIRECTOR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1, who is the director of the related sales_1 company.',
	SALES_COMPANY_DIRECTOR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the director of the related sales_1 company.',
	SALES_COMPANY_DIRECTOR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the manager of the related sales_1 company.',
	DELIV_COMPANY_SID NUMBER(38,0) NOT NULL COMMENT 'Surrogate key for the delivery company which is responsible for this store.',
	DELIV_COMPANY_NR VARCHAR(20) COMMENT 'The number which identifies the delivery company which is responsible for this store.',
	DELIV_COMPANY_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the delivery company which is responsible for this store..',
	DELIV_COMPANY_DIRECTOR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1, who is the director of the related delivery company.',
	DELIV_COMPANY_DIRECTOR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the director of the related delivery company.',
	DELIV_COMPANY_DIRECTOR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the manager of the related delivery company.',
	EXPANSION_COMPANY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the expansion company which is responsible for this store.',
	EXPANSION_COMPANY_NR VARCHAR(20) COMMENT 'The number which identifies the expansion company which is responsible for this store.',
	EXPANSION_COMPANY_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the expansion company which is responsible for this store.',
	BAL_SHEET_COMPANY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the balance sheet company, which is responsible for this store..',
	BAL_SHEET_COMPANY_NR VARCHAR(20) COMMENT 'The number which identifies the balance sheet company, which is responsible for this store..',
	BAL_SHEET_COMPANY_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the balance sheet company, which is responsible for this store..',
	OWNER_COMPANY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the owner company, which is responsible for this store..',
	OWNER_COMPANY_NR VARCHAR(20) COMMENT 'The number which identifies the owner company, which is responsible for this store..',
	OWNER_COMPANY_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the owner company, which is responsible for this store..',
	ORG_REGION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the related organizational region_1',
	ORG_REGION_NR VARCHAR(20) COMMENT 'The number which identifies the related organizational region.',
	ORG_REGION_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related organizational region.',
	ORG_REGION_MGR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1 who is currently filling the role of the manager of the related organizational region.',
	ORG_REGION_MGR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the person who is currently filling the role of the manager of the related organizational region.',
	ORG_REGION_MGR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the manager of the related organizational region.',
	COUNTRY_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the related country_1 organization.',
	COUNTRY_ORG_CD VARCHAR(2) COMMENT 'The code of the business country_1 for which this country_1 organization is responsible. (The business country_1 is not identical to a political country.)',
	COUNTRY_ORG_NR VARCHAR(20) COMMENT 'The number which identifies the related country_1 organization.',
	COUNTRY_ORG_NAME VARCHAR(100) NOT NULL COMMENT 'The name for the related country_1 organization. (name in group language, i.e. in German). (The country_1 organization is not necessarily identical with a political country_1,)',
	COUNTRY_ORG_MGR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1 who is responsible for the related country_1 organization.',
	COUNTRY_ORG_MGR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the manager who is responsible for the related country_1 organization.',
	COUNTRY_ORG_MGR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the manager who is responsible for the related country_1 organization.',
	COUNTRY_GRP_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the related organizational unit_1 which oversees the business in a group of countries.',
	COUNTRY_GRP_ORG_NR VARCHAR(20) COMMENT 'The number which identifies the related organizational unit_1 which oversees the business in a group of countries.',
	COUNTRY_GRP_ORG_NAME VARCHAR(100) NOT NULL COMMENT 'The name for the related organizational unit_1 which oversees the business in a group of countries.',
	COUNTRY_GRP_ORG_MGR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1 who is responsible for the related group of countries.',
	COUNTRY_GRP_ORG_MGR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the manager who is responsible for the related group of countries.',
	COUNTRY_GRP_ORG_MGR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the manager who is responsible for the related group of countries.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_DIM_STORE primary key (STORE_SID, DWH_VALID_FROM_TMSP)
)COMMENT='A store, seen as an internal organization unit_1 of the Schwarz Group. A store is located at a physical address. Its purpose is to offer goods to customers. Online-stores are not covered by this definition of a store. Note that the building that houses the store, is a resource item.'
;